INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(14488, 'plPL', 'Wezwanie doręczone', 'Jesteś, co? Dobrze. Czekałem na pomoc. Nie ma co zwlekać, nie?$b$bWeź ten zestaw i idź w głąb twierdzy, żeby doręczyć papiery szefowi tej parszywej kompanii chemicznej, Hummlowi. Pismo jest w środku. Jest tam też coś, co ochroni cię przed chemicznymi sztuczkami, których mogą spróbować. Kiedy przyjdzie pora, użyj któregoś z neutralizatorów, dobra?', 'Doręcz wezwanie sądowe aptekarzowi Hummlowi w Twierdzy Cienistego Kła.', '', 'Doręcz wezwanie sądowe aptekarzowi Hummlowi w Twierdzy Cienistego Kła.', '', '', '', '', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(14488, 'plPL', 'Nie przypominam sobie, żebym zamawiał firmę sprzątającą... Ależ tak, jestem aptekarz Hummel.$b$b...Chwileczkę, co to ma znaczyć? Myślisz, że te bezwartościowe papiery mnie powstrzymają? Ha!', 0);
