INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(15040, 'plPL', 'Kilka tygodni w tym żałosnym zamku da nam czas na opracowanie nowych produktów, a inni zdążą zapomnieć o tym niefortunnym... nieporozumieniu na Smoczych Pustkowiach.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(3927, 0, 0, 'plPL', 'Nie do wiary, zniszczyliście moją sforę... Teraz poczujcie mój gniew!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1320, 'plPL', 'Nareszcie wolny z tej nędznej celi! Pozwólcie, że zaprowadzę was na dziedziniec...', '', 0),
(1321, 'plPL', 'Zaiste, odwagi wam nie brakuje, skoro chcecie stawić czoła okropieństwom, które czają się za tymi drzwiami.', '', 0),
(1323, 'plPL', 'No i proszę!', '', 0),
(1324, 'plPL', 'Powodzenia z Arugalem. Muszę teraz szybko wracać do Hadreca.', '', 0),
(1328, 'plPL', 'Najwyższy czas, żeby ktoś zabił tego nędznika.', '', 0),
(1329, 'plPL', 'Choć raz się z tobą zgadzam... szumowino.', '', 0),
(1331, 'plPL', 'Chodźcie za mną, otworzę wam drzwi na dziedziniec.', '', 0),
(1332, 'plPL', 'Mam akurat zaklęcie, które otworzy te drzwi. Szkoda, że drzwi cel nie były zamknięte równie niedbale.', '', 0),
(1334, 'plPL', 'Proszę bardzo! Otwarte na oścież. Powodzenia w pokonaniu tego, co czeka dalej. Muszę natychmiast złożyć raport Kirin Torowi!', '', 0),
(1435, 'plPL', 'Kto śmie wchodzić w drogę Synom Arugala?', '', 0),
(1456, 'plPL', 'Zmieniłem zdanie, wierni słudzy, nie musicie prowadzić więźnia aż do mojej pracowni. Rozprawię się z nim tu i teraz.', '', 0),
(2801, 'plPL', 'Nareszcie! W końcu jestem wolny z tej celi!$b$bKirin Tor wysłał mnie z Dalaranu, żebym sprawdził postępy Arugala w pracy z nieumarłymi tu, w Srebrzystym Borze. Nie wiedzieliśmy, że czarodziej postradał zmysły.$b$bMuszę natychmiast donieść o tym bałaganie! Ale zanim odejdę, pozwól, że zdejmę magiczną blokadę z drzwi na dziedziniec.$b$b$GPokonałeś:Pokonałaś; Rethilgore\'a, więc może przetrwasz to, co czeka dalej...', '', 0),
(2802, 'plPL', 'Otwórz, proszę, drzwi na dziedziniec.', 'Otwórz, proszę, drzwi na dziedziniec.', 0),
(2803, 'plPL', 'Nareszcie! Ktoś, kto uwolni mnie z tej celi!$b$bNajwyższy egzekutor Hadrec wysłał nas, żebyśmy zebrali informacje o twierdzy i mogli opracować plan, jak raz na zawsze obalić Arugala.$b$bAle stary czarodziej ma w zanadrzu wiele sztuczek i wykryła nas magiczna osłona. Mnie wtrącono do tego lochu. Vincent nie miał tyle szczęścia.$b$bMuszę natychmiast wrócić do Hadreca i zdać mu raport. Ale najpierw otworzę ci wytrychem zamek w drzwiach na dziedziniec. Może spróbujesz szczęścia z wrogami, którzy czają się dalej.', '', 0),
(5680, 'plPL', 'Vincent! Ty i tobie podobne nędzne kreatury nie zdołacie przepędzić mnie i moich synów, tak jak nie zdołały tego żałosne resztki Kirin Toru.', '', 0),
(5681, 'plPL', 'Skoro nie chcesz służyć mojemu Panu mieczem i wiedzą o jego wrogach...', '', 0),
(5682, 'plPL', '...to twoje gnijące szczątki posłużą MNIE jako przestroga, co spotyka tych, którzy są na tyle głupi, by wtargnąć do mojej domeny!\n', '', 0),
(6115, 'plPL', 'Ty także będziesz służyć!', '', 0),
(6116, 'plPL', 'Kolejny pada!', '', 0),
(6535, 'plPL', 'Uwolnijcie swój gniew!', '', 0),
(14391, 'plPL', 'Trzymaj się ode mnie z daleka! Nie wiadomo, kiedy choroba znów mnie opanuje.$B$BPo prostu zostaw mnie w spokoju, zanim to się powtórzy.', '', 0),
(36652, 'plPL', 'Rozpocznij walkę.', 'Rozpocznij walkę.', 0),
(38586, 'plPL', 'Czy raczyli ci chociaż powiedzieć, kim jestem i dlaczego to robię?', '', 0),
(38591, 'plPL', 'Ale jakie to ma znaczenie. Czas z tym skończyć.', '', 0),
(38592, 'plPL', 'Baxter! Chodź tu i pomóż! NATYCHMIAST!', '', 0),
(38593, 'plPL', 'Już czas, Frye! Do ataku!', '', 0),
(38594, 'plPL', 'Aptekarze! Oddajcie życie za Koronę!', '', 0),
(38597, 'plPL', '...proszę, nie myśl o mnie źle.', '', 0),
(38600, 'plPL', '...czy tylko cię wykorzystują, tak jak wszystkich innych?', '', 0),
(48821, 'plPL', 'Natychmiast opuśćcie to przeklęte miejsce!', '', 0),
(48826, 'plPL', 'Intruzi w twierdzy! Do broni!', '', 0),
(48829, 'plPL', 'Nasza czujność jest wieczna...', '', 0);
